    def maxSubarraySum(self, nums: List[int]) -> int:
        from collections import defaultdict

        max_elem = max(nums)
        # If all elements are non-positive, we can't do better than the max element itself.
        if max_elem <= 0:
            return max_elem

        n = len(nums)
        # Segment tree nodes store: (sum, max_prefix, max_suffix, max_subarray)
        tree = [(0, 0, 0, 0)] * (2 * n)

